import{e as t,ab as r,a1 as i,m as o,r as s,p as n}from"./chunks/framework.BGh0NSIy.js";const g=JSON.parse('{"title":"Monthly Updates [October]","description":"October 2023 updates.","frontmatter":{"title":"Monthly Updates [October]","description":"October 2023 updates.","date":"2023-10-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/oct-2023.md","filePath":"posts/oct-2023.md"}'),l={name:"posts/oct-2023.md"};function d(p,e,m,h,c,f){const a=r("Post");return i(),o("div",null,[s(a,{authors:"nbats"}),e[0]||(e[0]=n('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Created a <strong><a href="https://rentry.co/fmhy-guides" target="_blank" rel="noreferrer">List of Guides</a></strong> on Rentry. This page is automated and updates itself anytime a new Rentry is added or removed from FMHY. You can also download the guides yourself by using this <a href="https://gist.github.com/Rust1667/efc055debaf4876e4de39cc0d32f18c1" target="_blank" rel="noreferrer">script</a>.</p></li><li><p>Made a <a href="/gaming/#pokémon-tools">Pokémon</a> section in Gaming Tools and an <a href="/internet-tools#email-tools">Email</a> section in Internet Tools.</p></li><li><p>Added <a href="https://i.imgur.com/mgYq8nF.png" target="_blank" rel="noreferrer">emojis</a> to indicate when we&#39;re linking 3rd party indexes or our storage page:</p></li></ul><p>🌐 = 3rd Party Indexes (i.e., /r/PiratedGames Mega, Awesome Lists, etc.)</p><p>↪️ = Storage Links</p><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="/ai/#ai-chatbots">Nova AI</a> in AI Chatbots. Provides free GPT-4 tokens.</p></li><li><p>Starred <a href="/gaming/#rom-sites">BlueROMs</a> in ROM Sites. A simple DDL site with lots of systems.</p></li><li><p>Starred <a href="/storage/#file-sharing-tools">Qiwi</a> in File Hosts. A fast host that is becoming popular in piracy circles.</p></li><li><p>Starred Moo and Media in <a href="/video/#drives--directories">Video Drives</a>. Fast drives with lots of content.</p></li><li><p>Starred <a href="/gaming/#rom-sites">WiiUDownloader</a> in ROM Sites. Updated more frequently than WiiUSBHelper.</p></li><li><p>Starred <a href="/video/#live-tv--sports">Time4TV</a> in Live TV. Fast streams and a wide variety of channels.</p></li><li><p>Starred <a href="/storage/#userscript-managers">Tampermonkey</a> in Userscript Managers. Updated more frequently than Greasemonkey.</p></li><li><p>Starred <a href="/storage/#compression-programs">PeaZip</a> in File Archivers. Open-source and supports many formats.</p></li><li><p>Starred <a href="/mobile/#android-streaming">Miru</a> in Android Streaming. An open-source, multi-format media app.</p></li><li><p>Starred <a href="/linux-macos/#mac-tools--apps">gibMacOS</a> in Mac Tools. Easily download macOS versions.</p></li><li><p>Starred <a href="/linux-macos/#mac-software">AppsTorrent</a> in Mac Software. A popular Mac software site with many apps.</p></li><li><p>Starred <a href="/video-tools">PlayPhrase</a> in Video Tools. Search the entire internet for specific video clips.</p></li><li><p>Starred <a href="/storage/#note-taking--to-do-apps">Magic ToDo</a> in To-Do Apps. An AI-powered automatic task breakdown tool.</p></li><li><p>Starred <a href="/misc/#health">SafeSubstance</a> in Health. Provides drug information and side effects.</p></li><li><p>Starred <a href="https://tinykittens.com/" target="_blank" rel="noreferrer">TinyKittens</a> in General Tools. A kitten rescue and donation website.</p></li></ul><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Removed RSLOAD, as they have uploaded a version of Malwarebytes bundled with the same malware that caused the recent FileCR controversy. We have emailed them; hopefully, they remove it soon so we can re-evaluate.</p></li><li><p>Removed marin.moe from Anime Streaming as it is redirecting to an unrelated domain now.</p></li><li><p>Removed AdGuard Extra and other adblock defenders as they are <a href="https://ibb.co/xgrtbBZ" target="_blank" rel="noreferrer">redundant</a> when using uBlock Origin.</p></li><li><p>Removed SteamSkins as Steam dropped support for them in the latest update.</p></li><li><p>Removed Saikou from Android Anime as their GitHub repository has been DMCA&#39;d.</p></li><li><p>Removed Uptobox from File Hosts as their data center was <a href="https://torrentfreak.com/uptobox-goes-dark-following-police-raids-on-french-datacenters-230920/" target="_blank" rel="noreferrer">raided by French police</a>.</p></li></ul>',9))])}const b=t(l,[["render",d]]);export{g as __pageData,b as default};
